/**
 * CountBadge. A lit pill sized to stay round at one
 * digit and stretch at three. Composes var(--echo-*).
 */
.echo-count-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  min-width: 20px;
  height: 20px;
  padding: 0 var(--echo-space-3);
  border-radius: var(--echo-radius-full);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-2xs);
  font-weight: var(--echo-weight-bold, 700);
  font-variant-numeric: tabular-nums;
  line-height: var(--echo-leading-none, 1);
}

/* The primary cap, like every lit control — not a second, lighter accent. */
.echo-count-badge[data-variant="accent"] {
  color: var(--echo-primary-cap-ink, var(--echo-text));
  background: linear-gradient(
    180deg,
    var(--echo-primary-cap-top) 0%,
    var(--echo-primary-cap-mid) 45%,
    var(--echo-primary-cap-base) 100%
  );
  /* A lit top edge, no halo — the library throws no outer glows. */
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.35 * var(--echo-gloss, 1))),
    inset 0 -1px 0 color-mix(in oklab, var(--echo-cast-ink, black) calc(0.25 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

.echo-count-badge[data-variant="neutral"] {
  color: var(--echo-text);
  background: linear-gradient(180deg, var(--echo-cap-highlight) 0%, var(--echo-cap) 100%);
  box-shadow: var(
    --echo-shadow-chip,
    inset 0 1px 0 rgb(255 255 255 / calc(0.15 * var(--echo-gloss, 1))),
    0 1px 2px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.4 * var(--echo-shade, 1) * 100%), transparent),
    0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent)
  );
}

/*
 * Motion. The badge pops into place on a spring when it appears, and each
 * new count rolls up into the face — so a number going up is seen to go up.
 */
.echo-count-badge {
  animation: echo-count-pop var(--echo-duration-pop) var(--echo-ease-pop);
}
.echo-count-badge__num {
  display: inline-block;
  animation: echo-count-roll var(--echo-duration-pop) var(--echo-ease-pop);
}
@keyframes echo-count-pop {
  from {
    transform: scale(0);
  }
}
@keyframes echo-count-roll {
  from {
    opacity: 0;
    transform: translateY(70%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .echo-count-badge,
  .echo-count-badge__num {
    animation: none;
  }
}

/**
 * CountBadge — a number worth noticing. The lit
 * sibling of Badge: where Badge names a state, CountBadge counts a thing.
 *
 * Static; consumes only var(--echo-*) via count-badge.css.
 */
import type { HTMLAttributes } from "react";
import "./count-badge.css";

/**
 * Renamed from `CountBadgeTone` when `tone` became Echo's status vocabulary.
 *
 * This was never a tone. `tone` is what a thing MEANS — `info`, `active`,
 * `warn`, `danger` (`EchoTone`) — and "accent or neutral" is a colour choice,
 * which is what `variant` already means everywhere else in Echo
 * (`PanelVariant`, `SkeletonVariant`, `HardwareButtonVariant`). A count badge
 * has no status to report; it reports a number.
 */
export type CountBadgeVariant = "accent" | "neutral";

export interface CountBadgeProps extends Omit<HTMLAttributes<HTMLSpanElement>, "children"> {
  count: number;
  /**
   * What the number counts, e.g. "unread messages". The accessible name
   * becomes "3 unread messages" — a bare "3" tells a screen-reader user
   * nothing.
   */
  label: string;
  /** Cap the display; above it renders as `${max}+`. Default 99. */
  max?: number;
  /** Render at zero instead of disappearing. Default false. */
  showZero?: boolean;
  variant?: CountBadgeVariant;
}

export function CountBadge({
  count,
  label,
  max = 99,
  showZero = false,
  variant = "accent",
  className,
  ...rest
}: CountBadgeProps) {
  if (count <= 0 && !showZero) return null;

  const clamped = count > max;
  const display = clamped ? `${max}+` : String(count);
  // Say the real number even when the face is capped: "127 unread messages"
  // is useful, "99+ unread messages" is a rendering detail.
  const spoken = `${count} ${label}`;

  return (
    <span
      className={["echo-count-badge", className].filter(Boolean).join(" ")}
      data-variant={variant}
      data-capped={clamped ? "" : undefined}
      role="status"
      aria-label={spoken}
      {...rest}
    >
      {/* Keyed by the number, so a new count mounts fresh and rolls in. */}
      <span key={display} className="echo-count-badge__num" aria-hidden="true">
        {display}
      </span>
    </span>
  );
}
